 39	    {0, -1, 0, 0, 0, 0, 0},        // 0
 40	    {-1, -1, -1, -1, -1, -1, -1},  // 1
 41	    {0, -1, 0, 0, 0, 1, 0},        // 2
 42	    {0, -1, 0, 0, 1, 1, 0},        // 3
 43	    {0, -1, 0, 5, 0, 0, 0},        // 4
 44	    {0, -1, 5, 5, 0, 0, 0},        // 5
 45	    {0, -1, 0, 0, 0, 0, 0},        // 6
 46	};
