 90	/**
 91	 * Prohibited directions when unfolding a pentagon.
 92	 *
 93	 * Indexes by two directions, both relative to the pentagon base cell. The first
 94	 * is the direction of the origin index and the second is the direction of the
 95	 * index to unfold. Direction refers to the direction from base cell to base
 96	 * cell if the indexes are on different base cells, or the leading digit if
 97	 * within the pentagon base cell.
 98	 *
 99	 * This previously included a Class II/Class III check but these were removed
100	 * due to failure cases. It's possible this could be restricted to a narrower
101	 * set of a failure cases. Currently, the logic is any unfolding across more
102	 * than one icosahedron face is not permitted.
103	 */
104	const bool FAILED_DIRECTIONS[7][7] = {
105	    {false, false, false, false, false, false, false},  // 0
106	    {false, false, false, false, false, false, false},  // 1
107	    {false, false, false, false, true, true, false},    // 2
108	    {false, false, false, false, true, false, true},    // 3
109	    {false, false, true, true, false, false, false},    // 4
110	    {false, false, true, false, false, false, true},    // 5
111	    {false, false, false, true, false, true, false},    // 6
112	};
