114	/**
115	 * Produces ijk+ coordinates for an index anchored by an origin.
116	 *
117	 * The coordinate space used by this function may have deleted
118	 * regions or warping due to pentagonal distortion.
119	 *
120	 * Coordinates are only comparable if they come from the same
121	 * origin index.
122	 *
123	 * Failure may occur if the index is too far away from the origin
124	 * or if the index is on the other side of a pentagon.
125	 *
126	 * @param origin An anchoring index for the ijk+ coordinate system.
127	 * @param index Index to find the coordinates of
128	 * @param out ijk+ coordinates of the index will be placed here on success
129	 * @return 0 on success, or another value on failure.
130	 */
131	int h3ToLocalIjk(H3Index origin, H3Index h3, CoordIJK *out) {
132	    int res = H3_GET_RESOLUTION(origin);
133	
134	    if (res != H3_GET_RESOLUTION(h3)) {
135	        return 1;
136	    }
137	
138	    int originBaseCell = H3_GET_BASE_CELL(origin);
139	    int baseCell = H3_GET_BASE_CELL(h3);
140	
141	    if (originBaseCell < 0 ||  // LCOV_EXCL_BR_LINE
142	        originBaseCell >= NUM_BASE_CELLS) {
143	        // Base cells less than zero can not be represented in an index
144	        return 1;
145	    }
146	    if (baseCell < 0 || baseCell >= NUM_BASE_CELLS) {  // LCOV_EXCL_BR_LINE
147	        // Base cells less than zero can not be represented in an index
148	        return 1;
149	    }
150	
151	    // Direction from origin base cell to index base cell
152	    Direction dir = CENTER_DIGIT;
153	    Direction revDir = CENTER_DIGIT;
154	    if (originBaseCell != baseCell) {
155	        dir = _getBaseCellDirection(originBaseCell, baseCell);
156	        if (dir == INVALID_DIGIT) {
157	            // Base cells are not neighbors, can't unfold.
158	            return 2;
159	        }
160	        revDir = _getBaseCellDirection(baseCell, originBaseCell);
161	        assert(revDir != INVALID_DIGIT);
162	    }
163	
164	    int originOnPent = _isBaseCellPentagon(originBaseCell);
165	    int indexOnPent = _isBaseCellPentagon(baseCell);
166	
167	    FaceIJK indexFijk = {0};
168	    if (dir != CENTER_DIGIT) {
169	        // Rotate index into the orientation of the origin base cell.
170	        // cw because we are undoing the rotation into that base cell.
171	        int baseCellRotations = baseCellNeighbor60CCWRots[originBaseCell][dir];
172	        if (indexOnPent) {
173	            for (int i = 0; i < baseCellRotations; i++) {
174	                h3 = _h3RotatePent60cw(h3);
175	
176	                revDir = _rotate60cw(revDir);
177	                if (revDir == K_AXES_DIGIT) revDir = _rotate60cw(revDir);
178	            }
179	        } else {
180	            for (int i = 0; i < baseCellRotations; i++) {
181	                h3 = _h3Rotate60cw(h3);
182	
183	                revDir = _rotate60cw(revDir);
184	            }
185	        }
186	    }
187	    // Face is unused. This produces coordinates in base cell coordinate space.
188	    _h3ToFaceIjkWithInitializedFijk(h3, &indexFijk);
189	
190	    if (dir != CENTER_DIGIT) {
191	        assert(baseCell != originBaseCell);
192	        assert(!(originOnPent && indexOnPent));
193	
194	        int pentagonRotations = 0;
195	        int directionRotations = 0;
196	
197	        if (originOnPent) {
198	            int originLeadingDigit = _h3LeadingNonZeroDigit(origin);
199	
200	            if (FAILED_DIRECTIONS[originLeadingDigit][dir]) {
201	                // TODO: We may be unfolding the pentagon incorrectly in this
202	                // case; return an error code until this is guaranteed to be
203	                // correct.
204	                return 3;
205	            }
206	
207	            directionRotations = PENTAGON_ROTATIONS[originLeadingDigit][dir];
208	            pentagonRotations = directionRotations;
209	        } else if (indexOnPent) {
210	            int indexLeadingDigit = _h3LeadingNonZeroDigit(h3);
211	
212	            if (FAILED_DIRECTIONS[indexLeadingDigit][revDir]) {
213	                // TODO: We may be unfolding the pentagon incorrectly in this
214	                // case; return an error code until this is guaranteed to be
215	                // correct.
216	                return 4;
217	            }
218	
219	            pentagonRotations = PENTAGON_ROTATIONS[revDir][indexLeadingDigit];
220	        }
221	
222	        assert(pentagonRotations >= 0);
223	        assert(directionRotations >= 0);
224	
225	        for (int i = 0; i < pentagonRotations; i++) {
226	            _ijkRotate60cw(&indexFijk.coord);
227	        }
228	
229	        CoordIJK offset = {0};
230	        _neighbor(&offset, dir);
231	        // Scale offset based on resolution
232	        for (int r = res - 1; r >= 0; r--) {
233	            if (isResolutionClassIII(r + 1)) {
234	                // rotate ccw
235	                _downAp7(&offset);
236	            } else {
237	                // rotate cw
238	                _downAp7r(&offset);
239	            }
240	        }
241	
242	        for (int i = 0; i < directionRotations; i++) {
243	            _ijkRotate60cw(&offset);
244	        }
245	
246	        // Perform necessary translation
247	        _ijkAdd(&indexFijk.coord, &offset, &indexFijk.coord);
248	        _ijkNormalize(&indexFijk.coord);
249	    } else if (originOnPent && indexOnPent) {
250	        // If the origin and index are on pentagon, and we checked that the base
251	        // cells are the same or neighboring, then they must be the same base
252	        // cell.
253	        assert(baseCell == originBaseCell);
254	
255	        int originLeadingDigit = _h3LeadingNonZeroDigit(origin);
256	        int indexLeadingDigit = _h3LeadingNonZeroDigit(h3);
257	
258	        if (FAILED_DIRECTIONS[originLeadingDigit][indexLeadingDigit]) {
259	            // TODO: We may be unfolding the pentagon incorrectly in this case;
260	            // return an error code until this is guaranteed to be correct.
261	            return 5;
262	        }
263	
264	        int withinPentagonRotations =
265	            PENTAGON_ROTATIONS[originLeadingDigit][indexLeadingDigit];
266	
267	        for (int i = 0; i < withinPentagonRotations; i++) {
268	            _ijkRotate60cw(&indexFijk.coord);
269	        }
270	    }
271	
272	    *out = indexFijk.coord;
273	    return 0;
274	}
