125	/**
126	 * Test that the neighbors (k-ring), if they can be found in the local IJ
127	 * coordinate space, can be converted back to indexes.
128	 */
129	void localIjToH3_gridDisk_assertions(H3Index h3) {
130	    int r = H3_GET_RESOLUTION(h3);
131	    t_assert(r <= 5, "resolution supported by test function (gridDisk)");
132	    int maxK = MAX_DISTANCES[r];
133	
134	    int sz = H3_EXPORT(maxGridDiskSize)(maxK);
135	    H3Index *neighbors = calloc(sz, sizeof(H3Index));
136	    int *distances = calloc(sz, sizeof(int));
137	
138	    H3_EXPORT(gridDiskDistances)(h3, maxK, neighbors, distances);
139	
140	    for (int i = 0; i < sz; i++) {
141	        if (neighbors[i] == 0) {
142	            continue;
143	        }
144	
145	        CoordIJ ij;
146	        // Don't consider indexes which we can't unfold in the first place
147	        if (H3_EXPORT(experimentalH3ToLocalIj)(h3, neighbors[i], &ij) == 0) {
148	            H3Index retrieved;
149	            t_assert(
150	                H3_EXPORT(experimentalLocalIjToH3)(h3, &ij, &retrieved) == 0,
151	                "retrieved index for unfolded coordinates");
152	            t_assert(retrieved == neighbors[i],
153	                     "round trip neighboring index matches expected");
154	        }
155	    }
156	
157	    free(distances);
158	    free(neighbors);
159	}
