878	 */
879	int H3_EXPORT(maxFaceCount)(H3Index h3) {
880	    // a pentagon always intersects 5 faces, a hexagon never intersects more
881	    // than 2 (but may only intersect 1)
882	    return H3_EXPORT(isPentagon)(h3) ? 5 : 2;
