885	/**
886	 * Find all icosahedron faces intersected by a given H3 index, represented
887	 * as integers from 0-19. The array is sparse; since 0 is a valid value,
888	 * invalid array values are represented as -1. It is the responsibility of
889	 * the caller to filter out invalid values.
890	 *
891	 * @param h3 The H3 index
892	 * @param out Output array. Must be of size maxFaceCount(h3).
893	 */
894	void H3_EXPORT(getIcosahedronFaces)(H3Index h3, int *out) {
895	    int res = H3_GET_RESOLUTION(h3);
896	    int isPent = H3_EXPORT(isPentagon)(h3);
897	
898	    // We can't use the vertex-based approach here for class II pentagons,
899	    // because all their vertices are on the icosahedron edges. Their
900	    // direct child pentagons cross the same faces, so use those instead.
901	    if (isPent && !isResolutionClassIII(res)) {
902	        // Note that this would not work for res 15, but this is only run on
903	        // Class II pentagons, it should never be invoked for a res 15 index.
904	        H3Index childPentagon = makeDirectChild(h3, 0);
905	        H3_EXPORT(getIcosahedronFaces)(childPentagon, out);
906	        return;
907	    }
908	
909	    // convert to FaceIJK
910	    FaceIJK fijk;
911	    _h3ToFaceIjk(h3, &fijk);
912	
913	    // Get all vertices as FaceIJK addresses. For simplicity, always
914	    // initialize the array with 6 verts, ignoring the last one for pentagons
915	    FaceIJK fijkVerts[NUM_HEX_VERTS];
916	    int vertexCount;
917	
918	    if (isPent) {
919	        vertexCount = NUM_PENT_VERTS;
920	        _faceIjkPentToVerts(&fijk, &res, fijkVerts);
921	    } else {
922	        vertexCount = NUM_HEX_VERTS;
923	        _faceIjkToVerts(&fijk, &res, fijkVerts);
924	    }
925	
926	    // We may not use all of the slots in the output array,
927	    // so fill with invalid values to indicate unused slots
928	    int faceCount = H3_EXPORT(maxFaceCount)(h3);
929	    for (int i = 0; i < faceCount; i++) {
930	        out[i] = INVALID_FACE;
931	    }
932	
933	    // add each vertex face, using the output array as a hash set
934	    for (int i = 0; i < vertexCount; i++) {
935	        FaceIJK *vert = &fijkVerts[i];
936	
937	        // Adjust overage, determining whether this vertex is
938	        // on another face
939	        if (isPent) {
940	            _adjustPentVertOverage(vert, res);
941	        } else {
942	            _adjustOverageClassII(vert, res, 0, 1);
943	        }
944	
945	        // Save the face to the output array
946	        int face = vert->face;
947	        int pos = 0;
948	        // Find the first empty output position, or the first position
949	        // matching the current face
950	        while (out[pos] != INVALID_FACE && out[pos] != face) pos++;
951	        out[pos] = face;
952	    }
953	}
