290	int localIjkToH3(H3Index origin, const CoordIJK *ijk, H3Index *out) {
291	    int res = H3_GET_RESOLUTION(origin);
292	    int originBaseCell = H3_GET_BASE_CELL(origin);
293	    if (originBaseCell < 0 ||  // LCOV_EXCL_BR_LINE
294	        originBaseCell >= NUM_BASE_CELLS) {
295	        // Base cells less than zero can not be represented in an index
296	        return 1;
297	    }
298	    int originOnPent = _isBaseCellPentagon(originBaseCell);
299	
300	    // This logic is very similar to faceIjkToH3
301	    // initialize the index
302	    *out = H3_INIT;
303	    H3_SET_MODE(*out, H3_HEXAGON_MODE);
304	    H3_SET_RESOLUTION(*out, res);
305	
306	    // check for res 0/base cell
307	    if (res == 0) {
308	        if (ijk->i > 1 || ijk->j > 1 || ijk->k > 1) {
309	            // out of range input
310	            return 1;
311	        }
312	
313	        const Direction dir = _unitIjkToDigit(ijk);
314	        const int newBaseCell = _getBaseCellNeighbor(originBaseCell, dir);
315	        if (newBaseCell == INVALID_BASE_CELL) {
316	            // Moving in an invalid direction off a pentagon.
317	            return 1;
318	        }
319	        H3_SET_BASE_CELL(*out, newBaseCell);
320	        return 0;
321	    }
322	
323	    // we need to find the correct base cell offset (if any) for this H3 index;
324	    // start with the passed in base cell and resolution res ijk coordinates
325	    // in that base cell's coordinate system
326	    CoordIJK ijkCopy = *ijk;
327	
328	    // build the H3Index from finest res up
329	    // adjust r for the fact that the res 0 base cell offsets the indexing
330	    // digits
331	    for (int r = res - 1; r >= 0; r--) {
332	        CoordIJK lastIJK = ijkCopy;
333	        CoordIJK lastCenter;
334	        if (isResolutionClassIII(r + 1)) {
335	            // rotate ccw
336	            _upAp7(&ijkCopy);
337	            lastCenter = ijkCopy;
338	            _downAp7(&lastCenter);
339	        } else {
340	            // rotate cw
341	            _upAp7r(&ijkCopy);
342	            lastCenter = ijkCopy;
343	            _downAp7r(&lastCenter);
344	        }
345	
346	        CoordIJK diff;
347	        _ijkSub(&lastIJK, &lastCenter, &diff);
348	        _ijkNormalize(&diff);
349	
350	        H3_SET_INDEX_DIGIT(*out, r + 1, _unitIjkToDigit(&diff));
351	    }
352	
353	    // ijkCopy should now hold the IJK of the base cell in the
354	    // coordinate system of the current base cell
355	
356	    if (ijkCopy.i > 1 || ijkCopy.j > 1 || ijkCopy.k > 1) {
357	        // out of range input
358	        return 2;
359	    }
360	
361	    // lookup the correct base cell
362	    Direction dir = _unitIjkToDigit(&ijkCopy);
363	    int baseCell = _getBaseCellNeighbor(originBaseCell, dir);
364	    // If baseCell is invalid, it must be because the origin base cell is a
365	    // pentagon, and because pentagon base cells do not border each other,
366	    // baseCell must not be a pentagon.
367	    int indexOnPent =
368	        (baseCell == INVALID_BASE_CELL ? 0 : _isBaseCellPentagon(baseCell));
369	
370	    if (dir != CENTER_DIGIT) {
371	        // If the index is in a warped direction, we need to unwarp the base
372	        // cell direction. There may be further need to rotate the index digits.
373	        int pentagonRotations = 0;
374	        if (originOnPent) {
375	            const Direction originLeadingDigit = _h3LeadingNonZeroDigit(origin);
376	            pentagonRotations =
377	                PENTAGON_ROTATIONS_REVERSE[originLeadingDigit][dir];
378	            for (int i = 0; i < pentagonRotations; i++) {
379	                dir = _rotate60ccw(dir);
380	            }
381	            // The pentagon rotations are being chosen so that dir is not the
382	            // deleted direction. If it still happens, it means we're moving
383	            // into a deleted subsequence, so there is no index here.
384	            if (dir == K_AXES_DIGIT) {
385	                return 3;
386	            }
387	            baseCell = _getBaseCellNeighbor(originBaseCell, dir);
388	
389	            // indexOnPent does not need to be checked again since no pentagon
390	            // base cells border each other.
391	            assert(baseCell != INVALID_BASE_CELL);
392	            assert(!_isBaseCellPentagon(baseCell));
393	        }
394	
395	        // Now we can determine the relation between the origin and target base
396	        // cell.
397	        const int baseCellRotations =
398	            baseCellNeighbor60CCWRots[originBaseCell][dir];
399	        assert(baseCellRotations >= 0);
400	
401	        // Adjust for pentagon warping within the base cell. The base cell
402	        // should be in the right location, so now we need to rotate the index
403	        // back. We might not need to check for errors since we would just be
404	        // double mapping.
405	        if (indexOnPent) {
406	            const Direction revDir =
407	                _getBaseCellDirection(baseCell, originBaseCell);
408	            assert(revDir != INVALID_DIGIT);
409	
410	            // Adjust for the different coordinate space in the two base cells.
411	            // This is done first because we need to do the pentagon rotations
412	            // based on the leading digit in the pentagon's coordinate system.
413	            for (int i = 0; i < baseCellRotations; i++) {
414	                *out = _h3Rotate60ccw(*out);
415	            }
416	
417	            const Direction indexLeadingDigit = _h3LeadingNonZeroDigit(*out);
418	            if (_isBaseCellPolarPentagon(baseCell)) {
419	                pentagonRotations =
420	                    PENTAGON_ROTATIONS_REVERSE_POLAR[revDir][indexLeadingDigit];
421	            } else {
422	                pentagonRotations =
423	                    PENTAGON_ROTATIONS_REVERSE_NONPOLAR[revDir]
424	                                                       [indexLeadingDigit];
425	            }
426	
427	            assert(pentagonRotations >= 0);
428	            for (int i = 0; i < pentagonRotations; i++) {
429	                *out = _h3RotatePent60ccw(*out);
430	            }
431	        } else {
432	            assert(pentagonRotations >= 0);
433	            for (int i = 0; i < pentagonRotations; i++) {
434	                *out = _h3Rotate60ccw(*out);
435	            }
436	
437	            // Adjust for the different coordinate space in the two base cells.
438	            for (int i = 0; i < baseCellRotations; i++) {
439	                *out = _h3Rotate60ccw(*out);
440	            }
441	        }
442	    } else if (originOnPent && indexOnPent) {
443	        const int originLeadingDigit = _h3LeadingNonZeroDigit(origin);
444	        const int indexLeadingDigit = _h3LeadingNonZeroDigit(*out);
445	
446	        const int withinPentagonRotations =
447	            PENTAGON_ROTATIONS_REVERSE[originLeadingDigit][indexLeadingDigit];
448	        assert(withinPentagonRotations >= 0);
449	
450	        for (int i = 0; i < withinPentagonRotations; i++) {
451	            *out = _h3Rotate60ccw(*out);
452	        }
453	    }
454	
455	    if (indexOnPent) {
456	        // TODO: There are cases in h3ToLocalIjk which are failed but not
457	        // accounted for here - instead just fail if the recovered index is
458	        // invalid.
459	        if (_h3LeadingNonZeroDigit(*out) == K_AXES_DIGIT) {
460	            return 4;
461	        }
462	    }
463	
464	    H3_SET_BASE_CELL(*out, baseCell);
465	    return 0;
466	}
