    99	
   100	    for (Direction d = K_AXES_DIGIT; d < INVALID_DIGIT; d++) {
   101	        if (d == K_AXES_DIGIT && H3_EXPORT(isPentagon)(h3)) {
   102	            continue;
   103	        }
