   136	    int *distances = calloc(sz, sizeof(int));
   137	
   138	    H3_EXPORT(gridDiskDistances)(h3, maxK, neighbors, distances);
   139	
   140	    for (int i = 0; i < sz; i++) {
   141	        if (neighbors[i] == 0) {
   142	            continue;
   143	        }
   144	
   145	        CoordIJ ij;
   146	        // Don't consider indexes which we can't unfold in the first place
   147	        if (H3_EXPORT(experimentalH3ToLocalIj)(h3, neighbors[i], &ij) == 0) {
   148	            H3Index retrieved;
   149	            t_assert(
   150	                H3_EXPORT(experimentalLocalIjToH3)(h3, &ij, &retrieved) == 0,
   151	                "retrieved index for unfolded coordinates");
   152	            t_assert(retrieved == neighbors[i],
