   161	void localIjToH3_traverse_assertions(H3Index h3) {
   162	    int r = H3_GET_RESOLUTION(h3);
   163	    t_assert(r <= 5, "resolution supported by test function (traverse)");
   164	    int k = MAX_DISTANCES[r];
   165	
   166	    CoordIJ ij;
   167	    t_assert(H3_EXPORT(experimentalH3ToLocalIj)(h3, h3, &ij) == 0,
   168	             "Got origin coordinates");
   169	
   170	    // This logic is from gridDiskDistancesUnsafe.
   171	    // 0 < ring <= k, current ring
   172	    int ring = 1;
   173	    // 0 <= direction < 6, current side of the ring
   174	    int direction = 0;
   175	    // 0 <= i < ring, current position on the side of the ring
   176	    int i = 0;
   177	
   178	    while (ring <= k) {
   179	        if (direction == 0 && i == 0) {
   180	            ij.i += NEXT_RING_DIRECTION.i;
   181	            ij.j += NEXT_RING_DIRECTION.j;
   182	        }
   183	
   184	        ij.i += DIRECTIONS[direction].i;
   185	        ij.j += DIRECTIONS[direction].j;
   186	
   187	        H3Index testH3;
   188	
   189	        int failed = H3_EXPORT(experimentalLocalIjToH3)(h3, &ij, &testH3);
   190	        if (!failed) {
   191	            t_assert(H3_EXPORT(isValidCell)(testH3),
   192	                     "test coordinates result in valid index");
   193	
   194	            CoordIJ expectedIj;
   195	            int reverseFailed =
   196	                H3_EXPORT(experimentalH3ToLocalIj)(h3, testH3, &expectedIj);
   197	            // If it doesn't give a coordinate for this origin,index pair that's
   198	            // OK.
   199	            if (!reverseFailed) {
   200	                if (expectedIj.i != ij.i || expectedIj.j != ij.j) {
   201	                    // Multiple coordinates for the same index can happen due to
   202	                    // pentagon distortion. In that case, the other coordinates
   203	                    // should also belong to the same index.
   204	                    H3Index testTestH3;
   205	                    t_assert(H3_EXPORT(experimentalLocalIjToH3)(
   206	                                 h3, &expectedIj, &testTestH3) == 0,
   207	                             "converted coordinates again");
   208	                    t_assert(testH3 == testTestH3,
   209	                             "index has normalizable coordinates in "
   210	                             "local IJ");
   211	                }
   212	            }
   213	        }
   214	
   215	        i++;
   216	        // Check if end of this side of the k-ring
   217	        if (i == ring) {
   218	            i = 0;
   219	            direction++;
   220	            // Check if end of this ring.
   221	            if (direction == 6) {
   222	                direction = 0;
   223	                ring++;
   224	            }
   225	        }
   226	    }
   227	}
