576	 * Given cube coords as doubles, round to valid integer coordinates. Algorithm
577	 * from https://www.redblobgames.com/grids/hexagons/#rounding
578	 * @param i   Floating-point I coord
579	 * @param j   Floating-point J coord
580	 * @param k   Floating-point K coord
581	 * @param ijk IJK coord struct, modified in place
582	 */
583	static void cubeRound(double i, double j, double k, CoordIJK *ijk) {
584	    int ri = round(i);
585	    int rj = round(j);
586	    int rk = round(k);
587	
588	    double iDiff = fabs((double)ri - i);
589	    double jDiff = fabs((double)rj - j);
590	    double kDiff = fabs((double)rk - k);
591	
592	    // Round, maintaining valid cube coords
593	    if (iDiff > jDiff && iDiff > kDiff) {
594	        ri = -rj - rk;
595	    } else if (jDiff > kDiff) {
596	        rj = -ri - rk;
597	    } else {
598	        rk = -ri - rj;
599	    }
600	
601	    ijk->i = ri;
602	    ijk->j = rj;
603	    ijk->k = rk;
604	}
605	
606	/**
607	 * Given two H3 indexes, return the line of indexes between them (inclusive).
608	 *
609	 * This function may fail to find the line between two indexes, for
610	 * example if they are very far apart. It may also fail when finding
611	 * distances for indexes on opposite sides of a pentagon.
612	 *
613	 * Notes:
614	 *
615	 *  - The specific output of this function should not be considered stable
616	 *    across library versions. The only guarantees the library provides are
617	 *    that the line length will be `gridDistance(start, end) + 1` and that
618	 *    every index in the line will be a neighbor of the preceding index.
619	 *  - Lines are drawn in grid space, and may not correspond exactly to either
620	 *    Cartesian lines or great arcs.
621	 *
622	 * @param start Start index of the line
623	 * @param end End index of the line
624	 * @param out Output array, which must be of size gridPathCellsSize(start, end)
625	 * @return 0 on success, or another value on failure.
626	 */
627	int H3_EXPORT(gridPathCells)(H3Index start, H3Index end, H3Index *out) {
628	    int distance = H3_EXPORT(gridDistance)(start, end);
629	    // Early exit if we can't calculate the line
630	    if (distance < 0) {
631	        return distance;
632	    }
633	
634	    // Get IJK coords for the start and end. We've already confirmed
635	    // that these can be calculated with the distance check above.
636	    CoordIJK startIjk = {0};
637	    CoordIJK endIjk = {0};
638	
639	    // Convert H3 addresses to IJK coords
640	    h3ToLocalIjk(start, start, &startIjk);
641	    h3ToLocalIjk(start, end, &endIjk);
642	
643	    // Convert IJK to cube coordinates suitable for linear interpolation
644	    ijkToCube(&startIjk);
645	    ijkToCube(&endIjk);
646	
647	    double iStep =
648	        distance ? (double)(endIjk.i - startIjk.i) / (double)distance : 0;
649	    double jStep =
650	        distance ? (double)(endIjk.j - startIjk.j) / (double)distance : 0;
651	    double kStep =
652	        distance ? (double)(endIjk.k - startIjk.k) / (double)distance : 0;
653	
654	    CoordIJK currentIjk = {startIjk.i, startIjk.j, startIjk.k};
655	    for (int n = 0; n <= distance; n++) {
656	        cubeRound((double)startIjk.i + iStep * n,
657	                  (double)startIjk.j + jStep * n,
658	                  (double)startIjk.k + kStep * n, &currentIjk);
659	        // Convert cube -> ijk -> h3 index
660	        cubeToIjk(&currentIjk);
661	        localIjkToH3(start, &currentIjk, &out[n]);
662	    }
663	
664	    return 0;
665	}

